/* No accounts or remote progress collection: learning records stay in this browser. */
const SUBJECTS={math:{name:'Math',symbol:'△',desc:'Count, compare, and solve. Build a strong foundation, one little discovery at a time.',short:'Numbers, shapes & patterns',color:'green'},english:{name:'English',symbol:'Aa',desc:'From first sounds to little stories. Grow confident with letters, words, and ideas.',short:'Letters, words & stories',color:'rose'},science:{name:'Science',symbol:'☀',desc:'Look closely. Ask why. Explore the wonderful world right outside your door.',short:'Observe, wonder & discover',color:'blue'}};
const KEY='little-sprout-v1';let state={records:{},sound:false,voice:'',rate:'normal',child:{name:'',gender:'',color:''}},storageOK=true,view='entry',subject='math',session=null;
const app=document.getElementById('app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// The learner's first name and gender stay in this browser only; nothing is sent anywhere.
function cleanName(n){return String(n||'').replace(/[^\p{L}\p{M}' -]/gu,'').replace(/\s+/g,' ').trim().slice(0,20).replace(/(^|[ -])(\p{L})/gu,(m,a,b)=>a+b.toUpperCase());}
// Favorite colors: the swatch shown on the entry screen; the page theme is in style.css (body[data-color]).
const COLORS={red:{name:'Red',hex:'#e5534b'},orange:{name:'Orange',hex:'#f08a3c'},yellow:{name:'Yellow',hex:'#f5c518'},green:{name:'Green',hex:'#5fae5a'},blue:{name:'Blue',hex:'#4a8fe0'},purple:{name:'Purple',hex:'#9061d6'},pink:{name:'Pink',hex:'#ec6fa8'}};
function cleanChild(c){const name=cleanName(c&&c.name);return {name,gender:name&&c&&['boy','girl'].includes(c.gender)?c.gender:'',color:name&&c&&COLORS[c.color]?c.color:''};}
function applyTheme(color){try{if(document.body&&document.body.dataset)document.body.dataset.color=COLORS[color]?color:'green';}catch(e){}}
const profileDone=()=>!!(childName()&&state.child.gender&&state.child.color);
const childName=()=>state.child&&state.child.name||'';
function validState(s){if(!s||typeof s!=='object'||!s.records||typeof s.records!=='object'||Array.isArray(s.records))return false;return Object.entries(s.records).every(([id,r])=>curriculum.some(m=>m.id===id)&&r&&Number.isInteger(r.best)&&r.best>=0&&r.best<=5&&Number.isInteger(r.attempts)&&r.attempts>0&&typeof r.mastered==='boolean'&&typeof r.activity==='boolean'&&typeof r.last==='string'&&Array.isArray(r.missed)&&r.missed.every(x=>curriculum.some(m=>m.id===x)));}
try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(validState(parsed))state={records:parsed.records,sound:!!parsed.sound,voice:typeof parsed.voice==='string'?parsed.voice:'',rate:parsed.rate==='slow'?'slow':'normal',child:cleanChild(parsed.child)};}localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;toast('Progress cannot save here. Export a backup from the grown-up corner.');}}
function record(id){return state.records[id];}function mastered(id){const r=record(id);return !!(r&&r.mastered);}
function count(s){return curriculum.filter(m=>(!s||m.subject===s)&&mastered(m.id)).length;}
function available(m){return m.number===1||mastered(`${m.subject}-${m.number-1}`);}
function next(s){return curriculum.find(m=>m.subject===s&&!mastered(m.id))||curriculum.find(m=>m.subject===s);}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4200);}
/* ---------- Read-aloud voice ----------
   Picks the most natural English voice this device offers, turns screen text into
   words a child would hear a person say, speaks in short phrases, and highlights
   whatever is being read. Everything stays in the browser. */
const RATES={slow:.78,normal:.9};
const canSpeak=()=>typeof window!=='undefined'&&'speechSynthesis'in window&&typeof SpeechSynthesisUtterance!=='undefined';
// Higher-quality voices first. Names vary by device: Edge/Windows "Natural", Apple "Premium/Enhanced", Chrome "Google".
const VOICE_HINTS=[/natural/i,/neural/i,/premium/i,/enhanced/i,/google us english/i,/google uk english female/i,/\bava\b/i,/samantha/i,/allison/i,/susan/i,/\bjenny\b/i,/\baria\b/i,/\bemma\b/i,/\bsonia\b/i,/\blibby\b/i,/serena/i,/karen/i,/moira/i,/\bzira\b/i,/daniel/i];
// Novelty and very robotic voices that would confuse or startle a young listener.
const SKIP_VOICES=/(albert|bad news|bahh|bells|boing|bubbles|cellos|deranged|good news|hysterical|jester|organ|superstar|trinoids|whisper|wobble|zarvox|junior|ralph|\bfred\b|kathy|grandpa|grandma|\beddy\b|\bflo\b|\breed\b|rocko|sandy|shelley|espeak)/i;
function voiceScore(v){let s=0;const i=VOICE_HINTS.findIndex(r=>r.test(v.name));if(i>=0)s+=100-i*3;if(/^en[-_]US/i.test(v.lang))s+=30;else if(/^en[-_](GB|AU|CA|IE|NZ)/i.test(v.lang))s+=20;if(v.default)s+=5;return s;}
function voiceList(){if(!canSpeak())return [];return speechSynthesis.getVoices().filter(v=>/^en/i.test(v.lang)&&!SKIP_VOICES.test(v.name)).sort((a,b)=>voiceScore(b)-voiceScore(a)||a.name.localeCompare(b.name));}
function pickVoice(){const vs=voiceList();return vs.find(v=>v.name===state.voice)||vs[0]||null;}
if(canSpeak()&&speechSynthesis.addEventListener)speechSynthesis.addEventListener('voiceschanged',()=>{if(view==='parent'){const sel=document.getElementById('voiceSelect');if(sel)sel.innerHTML=voiceOptions();}});
const PUNCT={'.':'period','?':'question mark',',':'comma','!':'exclamation mark'};
// Turn on-screen text into natural spoken words.
function speakable(s){let t=String(s);
  t=t.replace(/^Count the dots:\s*(●\s*)+$/,'Count the dots you see.');
  t=t.replace(/((?:●\s*)+)/g,m=>{const n=(m.match(/●/g)||[]).length;return n===1?'one dot ':n+' dots ';});
  t=t.replace(/(\d+)\s*\+\s*__\s*=\s*(\d+)/g,'$1 plus what makes $2?');
  t=t.replace(/(\d+)\s*\+\s*(\d+)\s*=\s*\?/g,'$1 plus $2 equals what?').replace(/(\d+)\s*-\s*(\d+)\s*=\s*\?/g,'$1 take away $2 equals what?');
  t=t.replace(/(\d)\s*-\s*(\d)/g,'$1 take away $2').replace(/(\d)\s*\+\s*(\d)/g,'$1 plus $2').replace(/\s=\s/g,' equals ');
  t=t.replace(/__/g,'blank');
  t=t.replace(/\b([a-z])_([a-z])\s*\((\w+)\)\.?/gi,'$1, blank, $2. As in $3.');
  t=t.replace(/\b([a-z])-([a-z])-([a-z])\b/gi,'$1, $2, $3');
  t=t.replace(/([A-Za-z0-9])_(?=\W|$)/g,'$1, blank');
  t=t.replace(/\b(small|capital) ([A-Za-z])\b/g,'$1 letter $2');
  t=t.replace(/,\s*\.\.\.\s*$/,'. What comes next?').replace(/\.\.\.\s*$/,' what?').replace(/\.\.\./g,' ');
  t=t.replace(/\s+([;.,?])/g,'$1').replace(/\s*\/\s*/g,', ').replace(/[“”]/g,'').replace(/\s+/g,' ').trim();
  return t;}
// Speak an answer choice so it sounds right on its own.
function speakChoice(o,q){const p=q?q.prompt:'';if(PUNCT[o])return PUNCT[o];
  const pair=o.match(/^([A-Z]) ([a-z])$/);if(pair)return `capital letter ${pair[1]} and small letter ${pair[2]}`;
  if(/^[A-Za-z]$/.test(o)&&q&&q.options.every(x=>/^[A-Za-z]$/.test(x))){if(/capital|small/i.test(p))return (o===o.toUpperCase()?'capital letter ':'small letter ')+o;return 'the letter '+o;}
  return speakable(o);}
const sentences=s=>String(s).match(/[^.!?]+[.!?]+["”’]?|[^.!?]+$/g)?.map(x=>x.trim()).filter(Boolean)||[];
// Fixed lines, so each one can have a recording.
const PRAISE=['You found it!','Yes! Great looking.','That’s it!','Wonderful thinking!','You got it!','Super job!'];
const RETRY=['Not quite yet. Have another look.','Good try! Let’s look again.','Hmm, try a different one.','So close. You can try again.'];
const RESULT={preview:{title:'Preview complete!',line:'This preview has not changed your progress.'},pass:{title:'A little more grown!',line:'You practiced, you remembered, and you tried it at home. This step is mastered!'},again:{title:'Every try helps you grow!',line:'You finished today’s practice, and that’s worth celebrating. Look back at the lesson and try again when you’re ready. Get 4 of 5 on your first try to open the next step.'}};
// Names that have their own Storyteller recording (any other name uses the device voice for the greeting).
const NAME_CLIPS={fanu:'Fanu',fife:'Fife'};
const LINES={'pick-boy':'Boy!','pick-girl':'Girl!',askColor:'What is your favorite color?','hi-friend':'Welcome, little sprout!','back-friend':'Welcome back, little sprout!',askName:'Hello there! What is your name?',askGender:'Are you a boy or a girl?',welcomeRest:'I’m so happy you’re here. Let’s learn and grow together!',backRest:'Let’s learn and grow today!',hint:'Here is a little hint.',home:'Now try it at home.',on:'Read aloud is on. Let’s learn together.',hello:'Hello! I will read with you today.',sample:'Hello, little sprout! Let’s count together. One, two, three. You found it!'};
// "Is it 1, 3, 0, or 2?" — pieces keep track of which answer button each part belongs to.
function choicesLine(q){const last=q.options.length-1;const pieces=q.options.map((o,i)=>({i,text:(i===0?'Is it ':'')+(i===last?'or ':'')+speakChoice(o,q).replace(/[.?!]+$/,'')+(i===last?'?':', ')}));return {text:pieces.map(x=>x.text).join(''),pieces};}
function questionRef(q){const m=curriculum.find(x=>x.id===(q.sourceId||(session&&session.m.id)))||(session&&session.m);let j=m?m.questions.findIndex(x=>x.prompt===q.prompt):-1;return {m,j};}
// Every spoken line, grouped by audio file. Used by the recording script and by the player.
function clipScript(){const files={common:[]};const c=files.common;
  PRAISE.forEach((t,i)=>c.push({key:'P'+i,text:t}));RETRY.forEach((t,i)=>c.push({key:'R'+i,text:t}));
  Object.entries(RESULT).forEach(([k,v])=>{c.push({key:'T-'+k,text:v.title});c.push({key:'X-'+k,text:v.line});});
  Object.entries(LINES).forEach(([k,v])=>c.push({key:k,text:v}));Object.entries(COLORS).forEach(([k,v])=>c.push({key:'color-'+k,text:v.name+'!'}));Object.entries(NAME_CLIPS).forEach(([k,n])=>{c.push({key:'hi-'+k,text:'Welcome, '+n+'!'});c.push({key:'back-'+k,text:'Welcome back, '+n+'!'});});
  for(const m of curriculum){const f=files[m.id]=[];sentences(m.learn).forEach((t,i)=>f.push({key:'L'+i,text:t}));f.push({key:'A',text:speakable(m.activity)});
    m.questions.forEach((q,j)=>{f.push({key:'Q'+j,text:speakable(q.prompt)});f.push({key:'C'+j,text:choicesLine(q).text});f.push({key:'W'+j,text:speakable(q.why)});});}
  return files;}
function learnParts(m,els=[]){return sentences(m.learn).map((t,i)=>({text:t,el:els[i],clip:m.id+':L'+i}));}

/* Player. "Storyteller" plays the natural recordings in voice/ ; any other choice
   (or a missing recording) uses the device's own speech voices. */
const hasRecordings=()=>typeof VOICE_CLIPS!=='undefined'&&!!VOICE_CLIPS;
const useStoryteller=()=>hasRecordings();
const clipRange=c=>{if(!c||!hasRecordings())return null;const [f,k]=c.split(':');return VOICE_CLIPS[f]&&VOICE_CLIPS[f][k]?{file:f,range:VOICE_CLIPS[f][k]}:null;};
let speechRun=0,player=null,audioUnlocked=false;
function getPlayer(){if(!player&&typeof Audio!=='undefined'){player=new Audio();player.preload='auto';}return player;}
// iOS and some browsers only allow sound after a tap: prime the player on the first one.
if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('pointerdown',()=>{if(audioUnlocked)return;const a=getPlayer();if(!a)return;audioUnlocked=true;if(!a.src){a.src='data:audio/mpeg;base64,';}a.play().then(()=>a.pause()).catch(()=>{});},{capture:true});
function clearHighlight(){if(app.querySelectorAll)app.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));}
function highlight(el){clearHighlight();if(el&&el.classList)el.classList.add('speaking');}
function stopSpeaking(){speechRun++;if(canSpeak())speechSynthesis.cancel();if(player)try{player.pause();}catch(e){}clearHighlight();setSpeakingUI(false);}
function setSpeakingUI(on){if(!app.querySelectorAll)return;app.querySelectorAll('[data-read]').forEach(b=>{if(!b.dataset.label)b.dataset.label=b.textContent;b.textContent=on?'■ Stop reading':b.dataset.label;b.classList.toggle('reading',on);});}
// Play one recorded line; resolves when it ends. onTick gets 0..1 progress for word-group highlighting.
function playRange(file,[a,b],run,onTick){return new Promise((resolve,reject)=>{const au=getPlayer();if(!au)return reject(Error('no audio'));
  audioSource(file).then(src=>{if(run!==speechRun)return resolve();const go=()=>{try{au.currentTime=a;}catch(e){return reject(e);}au.playbackRate=state.rate==='slow'?.86:1;
    au.play().then(()=>{const tick=()=>{if(run!==speechRun){au.pause();return resolve();}const t=au.currentTime;if(onTick)onTick(Math.max(0,Math.min(1,(t-a)/(b-a))));if(t>=b||au.ended){au.pause();resolve();}else requestAnimationFrame(tick);};requestAnimationFrame(tick);}).catch(reject);};
  if(au.getAttribute('src')!==src){au.src=src;au.addEventListener('loadedmetadata',go,{once:true});au.addEventListener('error',()=>reject(Error('load')),{once:true});au.load();}else go();});});}
// Load a module's audio fully into memory so jumping to any line works on every host
// (some servers do not allow seeking inside a file). Opened from disk, fetch is blocked, so use the file directly.
const audioCache={};
function audioSource(file){const url='voice/'+file+'.mp3';if(!audioCache[file])audioCache[file]=(typeof fetch==='function'&&location.protocol!=='file:'?fetch(url).then(r=>{if(!r.ok)throw Error('load');return r.blob();}).then(b=>URL.createObjectURL(b)):Promise.reject()).catch(()=>url);return audioCache[file];}
function preloadAudio(m){if(useStoryteller()&&m){audioSource(m.id);audioSource('common');}}
async function playRecorded(parts,run){for(let i=0;i<parts.length;i++){const p=parts[i];if(run!==speechRun)return;const c=clipRange(p.clip);
    if(!c)throw Object.assign(Error('missing'),{from:i});
    highlight(p.el);let onTick=null;
    if(p.pieces){const total=p.pieces.reduce((n,x)=>n+x.text.length,0);onTick=f=>{let acc=0;for(const x of p.pieces){acc+=x.text.length/total;if(f<=acc+0.02){highlight(x.el);break;}}};}
    try{await playRange(c.file,c.range,run,onTick);}catch(e){throw Object.assign(e,{from:i});}
    if(run!==speechRun)return;await new Promise(r=>setTimeout(r,p.pieces?120:220));}}
function speakDevice(parts,run){if(!canSpeak()){toast('Read aloud is unavailable in this browser. A grown-up can read with you.');setSpeakingUI(false);return;}const voice=pickVoice();
  const chunks=parts.flatMap(p=>p.pieces?p.pieces.map(x=>({t:x.text,el:x.el})):sentences(p.text).map(t=>({t,el:p.el})));if(!chunks.length){setSpeakingUI(false);return;}
  setTimeout(()=>{if(run!==speechRun)return;chunks.forEach((c,i)=>{const u=new SpeechSynthesisUtterance(c.t);if(voice){u.voice=voice;u.lang=voice.lang;}else u.lang='en-US';u.rate=RATES[state.rate]||RATES.normal;u.pitch=1.05;
    u.onstart=()=>{if(run===speechRun)highlight(c.el);};
    u.onend=u.onerror=()=>{if(run!==speechRun||i<chunks.length-1)return;clearHighlight();setSpeakingUI(false);};
    speechSynthesis.speak(u);});},60);}
// parts: [{text, el, clip?, pieces?}] — read in order, highlighting el (or each piece's el) as it is heard.
// Browsers only allow sound after the first tap or key press. Speech asked for before that waits, then plays on the first tap.
let pendingSpeech=null;
const needsTap=()=>typeof navigator!=='undefined'&&navigator.userActivation&&!navigator.userActivation.hasBeenActive;
if(typeof document!=='undefined'&&document.addEventListener){const go=e=>{if(!pendingSpeech)return;if(e&&e.target&&e.target.closest&&e.target.closest('[data-read]')){pendingSpeech=null;return;}const p=pendingSpeech;pendingSpeech=null;speak(p);};document.addEventListener('pointerdown',go,{capture:true});document.addEventListener('keydown',go,{capture:true});}
function speakSoon(parts){if(needsTap()){pendingSpeech=parts;return;}speak(parts);}
function speak(parts){pendingSpeech=null;parts=parts.filter(p=>p&&p.text);stopSpeaking();const run=speechRun;if(!parts.length)return;setSpeakingUI(true);
  if(useStoryteller()&&parts.some(p=>clipRange(p.clip))){playRecorded(parts,run).then(()=>{if(run===speechRun){clearHighlight();setSpeakingUI(false);}}).catch(e=>{if(run!==speechRun)return;if(e&&e.name==='NotAllowedError'){clearHighlight();setSpeakingUI(false);pendingSpeech=parts.slice(e.from||0);return;}speakDevice(parts.slice(e.from||0),run);});return;}
  speakDevice(parts,run);}
function say(s,clip){speak([{text:speakable(s),clip}]);}
function autoSpeak(s,clip){if(state.sound)say(s,clip);}
function autoSpeakParts(p){if(state.sound)speak(p);}
// What to read for the current lesson screen, linked to the elements to highlight.
function readParts(){const s=session;if(!s)return [];const m=s.m;
  if(s.step==='learn')return learnParts(m,[...app.querySelectorAll('.lesson-copy .sentence')]);
  if(s.step==='activity'){const box=app.querySelector('.activity-box');return [{text:LINES.home,el:box,clip:'common:home'},{text:speakable(m.activity),el:box,clip:m.id+':A'}];}
  if(s.step==='quiz'){const q=s.questions[s.index],btns=[...app.querySelectorAll('[data-answer]')],{m:src,j}=questionRef(q),line=choicesLine(q);
    const id=j>=0?src.id:null;line.pieces.forEach(x=>x.el=btns[x.i]);
    return [{text:speakable(q.prompt),el:app.querySelector('.question'),clip:id&&id+':Q'+j},{text:line.text,pieces:line.pieces,clip:id&&id+':C'+j}];}
  if(s.step==='result'){const k=resultKind(s),t=app.querySelector('.result-title'),p=app.querySelector('.result-line');return [{text:RESULT[k].title,el:t,clip:'common:T-'+k},{text:RESULT[k].line,el:p,clip:'common:X-'+k}];}
  return [];}
function resultKind(s){return s.preview?'preview':s.score>=4?'pass':'again';}
let praiseTurn=0,retryTurn=0;
function setView(v){stopSpeaking();view=v;document.getElementById('homeNav').classList.toggle('active',v!=='parent');document.getElementById('parentNav').classList.toggle('active',v==='parent');render();window.scrollTo(0,0);}
function art(s){if(s==='math')return `<svg viewBox="0 0 260 130" aria-hidden="true"><circle cx="62" cy="65" r="36" fill="#e9b650"/><rect x="102" y="34" width="64" height="64" rx="10" fill="#407b63" transform="rotate(-10 134 66)"/><path d="M192 99 L226 31 L260 99Z" fill="#f1f4d8"/><text x="43" y="80" fill="#184e43" font-size="44" font-family="Arial">1</text><text x="113" y="80" fill="#f1f4d8" font-size="39" font-family="Arial">2</text><text x="214" y="90" fill="#184e43" font-size="31" font-family="Arial">3</text></svg>`;if(s==='english')return `<svg viewBox="0 0 260 130" aria-hidden="true"><path d="M35 100V29Q80 11 128 38Q170 11 224 29V100Q172 83 128 109Q80 83 35 100" fill="#fff8ed"/><path d="M128 39V108" stroke="#d8c3ac" stroke-width="2"/><text x="52" y="78" fill="#8c503a" font-size="48" font-family="Georgia">A</text><text x="152" y="78" fill="#8c503a" font-size="48" font-family="Georgia">a</text><path d="M58 90H102M153 91H200" stroke="#dbc8b4" stroke-width="3"/><path d="M126 17L132 40L148 26" fill="none" stroke="#608265" stroke-width="4"/></svg>`;return `<svg viewBox="0 0 260 130" aria-hidden="true"><circle cx="195" cy="39" r="21" fill="#efc968"/><path d="M93 115V42" stroke="#43785a" stroke-width="5"/><path d="M91 77Q39 81 48 38Q88 35 91 77M96 92Q143 92 143 52Q99 50 96 92" fill="#76a48a"/><path d="M67 108H123L116 127H75Z" fill="#b16b4b"/><circle cx="165" cy="90" r="23" fill="none" stroke="#39566a" stroke-width="7"/><path d="M181 108L202 128" stroke="#39566a" stroke-width="9" stroke-linecap="round"/></svg>`;}
function garden(){return `<svg class="garden-art" viewBox="0 0 510 300" role="img" aria-label="A cheerful garden with flowers, leaves, and a little butterfly"><ellipse cx="257" cy="275" rx="222" ry="12" fill="#e5e9d5"/><path d="M84 272L98 201H396L413 272Z" fill="#ddd9bd"/><path d="M94 223H402M90 246H407" stroke="#c9c6a7" stroke-width="2"/><path d="M151 203V112M257 203V73M363 203V139" stroke="#426d50" stroke-width="7"/><path d="M150 178Q97 174 108 136Q148 133 150 178M155 157Q199 161 196 121Q157 121 155 157M259 155Q212 155 210 111Q253 111 259 155M263 125Q315 126 313 89Q270 88 263 125M362 191Q322 191 319 156Q358 152 362 191" fill="#86a978"/><g fill="#e9bd60"><circle cx="257" cy="46" r="22"/><circle cx="232" cy="62" r="22"/><circle cx="241" cy="89" r="22"/><circle cx="274" cy="87" r="22"/><circle cx="281" cy="59" r="22"/></g><circle cx="257" cy="68" r="23" fill="#184e43"/><circle cx="251" cy="64" r="2" fill="white"/><circle cx="264" cy="64" r="2" fill="white"/><path d="M251 75Q258 81 265 74" fill="none" stroke="white" stroke-width="2"/><g fill="#ceaa98"><circle cx="153" cy="86" r="18"/><circle cx="131" cy="105" r="18"/><circle cx="145" cy="125" r="18"/><circle cx="169" cy="121" r="18"/><circle cx="173" cy="98" r="18"/></g><circle cx="152" cy="105" r="17" fill="#f5efce"/><circle cx="147" cy="104" r="1.6" fill="#184e43"/><circle cx="157" cy="104" r="1.6" fill="#184e43"/><path d="M147 110Q153 115 158 109" fill="none" stroke="#184e43" stroke-width="1.5"/><path d="M332 133Q351 87 364 119Q378 90 396 133Q370 151 332 133" fill="#d9e1f1"/><circle cx="363" cy="132" r="15" fill="#7192a4"/><circle cx="359" cy="132" r="1.5" fill="white"/><circle cx="368" cy="132" r="1.5" fill="white"/><path d="M402 50Q375 20 370 45Q370 63 401 64Q423 28 434 45Q439 68 402 65" fill="#cfaa98"/><path d="M402 51L401 71" stroke="#184e43" stroke-width="3"/><path d="M56 105l8-4m-5-5v12M446 170l8-4m-5-5v12" stroke="#9fae7c" stroke-width="2"/><circle cx="73" cy="167" r="4" fill="#cfaa98"/><circle cx="329" cy="33" r="3" fill="#9fae7c"/></svg>`;}
function render(){applyTheme(state.child&&state.child.color);document.getElementById('soundToggle').textContent=state.sound?'♫ Read aloud: on':'♫ Read aloud: off';document.getElementById('soundToggle').setAttribute('aria-pressed',String(state.sound));if(view==='entry')entry();else if(view==='hello')hello();else if(view==='home')home();else if(view==='path')path();else if(view==='parent')parent();else lesson();if(!storageOK)app.insertAdjacentHTML('afterbegin','<p class="storage-warning">Browser storage is unavailable. Your progress may disappear when you close this page. Export a backup in the grown-up corner.</p>');}
function avatar(g){const c=g==='boy'?'#7192a4':g==='girl'?'#c98f7a':'#799e63';return `<svg class="avatar" viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="56" fill="${c}" opacity=".18"/><path d="M60 100V58" stroke="#426d50" stroke-width="6" stroke-linecap="round"/><path d="M58 70Q24 70 28 40Q56 38 58 70M62 62Q94 62 92 32Q64 30 62 62" fill="#86a978"/><circle cx="60" cy="40" r="17" fill="${c}"/><circle cx="54" cy="38" r="2.2" fill="#fff"/><circle cx="66" cy="38" r="2.2" fill="#fff"/><path d="M53 46Q60 52 67 46" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round"/>${g==='girl'?'<path d="M60 22l-9-6v12zM60 22l9-6v12z" fill="#e9bd60"/><circle cx="60" cy="22" r="3" fill="#e9bd60"/>':g==='boy'?'<path d="M44 30Q60 12 76 30Z" fill="#e9bd60"/><path d="M74 29h10" stroke="#e9bd60" stroke-width="4" stroke-linecap="round"/>':''}</svg>`;}
function greetParts(back){const name=childName(),key=name.toLowerCase(),known=!!NAME_CLIPS[key];
  return [{text:known?(back?'Welcome back, ':'Welcome, ')+name+'!':LINES[back?'back-friend':'hi-friend'],el:app.querySelector('.hello-name'),clip:'common:'+(back?'back-':'hi-')+(known?key:'friend')},{text:back?LINES.backRest:LINES.welcomeRest,el:app.querySelector('.hello-sub'),clip:'common:'+(back?'backRest':'welcomeRest')}];}
function entry(){const c=state.child||{};app.innerHTML=`<section class="entry"><form class="entry-card" id="entryForm" novalidate>${avatar(c.gender)}<h1>Hello there!</h1><p class="entry-lead">Let’s get to know you before we start learning.</p><button type="button" class="secondary read-small" data-read-entry>♫ Read it to me</button>
<label class="entry-field" for="childName"><span class="entry-q">What’s your name?</span><input id="childName" name="childName" type="text" maxlength="20" autocomplete="off" autocapitalize="words" spellcheck="false" placeholder="Type your name" value="${esc(c.name||'')}"></label>
<fieldset class="entry-field gender"><legend class="entry-q">Are you a boy or a girl?</legend><div class="gender-options"><label class="gender-choice"><input type="radio" name="gender" value="boy" ${c.gender==='boy'?'checked':''}><span>${avatar('boy')}Boy</span></label><label class="gender-choice"><input type="radio" name="gender" value="girl" ${c.gender==='girl'?'checked':''}><span>${avatar('girl')}Girl</span></label></div></fieldset>
<fieldset class="entry-field colors"><legend class="entry-q">What’s your favorite color?</legend><div class="color-options">${Object.entries(COLORS).map(([k,v])=>`<label class="color-choice"><input type="radio" name="color" value="${k}" ${c.color===k?'checked':''}><span><i style="background:${v.hex}"></i>${v.name}</span></label>`).join('')}</div></fieldset>
<p class="entry-error" id="entryError" role="alert"></p><button class="primary entry-go" type="submit">Let’s go! <span>→</span></button><p class="entry-note">A grown-up can help type. Your name stays on this device only.</p></form></section>`;
  const f=document.getElementById('entryForm'),input=document.getElementById('childName');
  const rb=app.querySelector('[data-read-entry]');if(rb){rb.setAttribute('data-read','');rb.onclick=()=>{if(rb.classList.contains('reading'))return stopSpeaking();speak([{text:LINES.askName,el:app.querySelector('label.entry-field .entry-q'),clip:'common:askName'},{text:LINES.askGender,el:app.querySelector('.gender .entry-q'),clip:'common:askGender'}]);};}
  f.oninput=f.onchange=()=>{const err=document.getElementById('entryError');if(err)err.textContent='';};
  f.onsubmit=e=>{e.preventDefault();const name=cleanName(input.value),g=(f.querySelector('input[name="gender"]:checked')||{}).value,col=(f.querySelector('input[name="color"]:checked')||{}).value;const err=document.getElementById('entryError');
    if(!name){err.textContent='Please type your name.';input.focus();return;}if(!g){err.textContent='Please choose boy or girl.';return;}if(!col){err.textContent='Please choose your favorite color.';return;}
    state.child={name,gender:g,color:col};save();applyTheme(col);freshGreeting=true;setView('hello');speak(greetParts(false));};
  const askName=()=>[{text:LINES.askName,el:app.querySelector('label.entry-field .entry-q'),clip:'common:askName'}],askGender=()=>[{text:LINES.askGender,el:app.querySelector('.gender .entry-q'),clip:'common:askGender'}];
  let askedGender=false;const maybeAskGender=()=>{if(askedGender||!cleanName(input.value)||f.querySelector('input[name="gender"]:checked'))return;askedGender=true;speak(askGender());};
  input.onblur=()=>setTimeout(maybeAskGender,300);input.onkeydown=e=>{if(e.key==='Enter'&&cleanName(input.value)&&!f.querySelector('input[name="gender"]:checked')){e.preventDefault();input.blur();}};
  const askColor=()=>[{text:LINES.askColor,el:app.querySelector('.colors .entry-q'),clip:'common:askColor'}];
  f.querySelectorAll('input[name="gender"]').forEach(r=>r.addEventListener('change',()=>{askedGender=true;const more=f.querySelector('input[name="color"]:checked')?[]:askColor();speak([{text:r.value==='boy'?'Boy!':'Girl!',el:r.nextElementSibling,clip:'common:pick-'+r.value},...more]);}));
  f.querySelectorAll('input[name="color"]').forEach(r=>r.addEventListener('change',()=>{applyTheme(r.value);speak([{text:COLORS[r.value].name+'!',el:r.nextElementSibling,clip:'common:color-'+r.value}]);}));
  speakSoon(c.name&&c.gender&&!c.color?askColor():askName());}
function hello(){const c=state.child,back=!freshGreeting;const autoGreet=back;freshGreeting=false;app.innerHTML=`<section class="entry"><div class="entry-card hello-card">${avatar(c.gender)}<h1 class="hello-name">${back?'Welcome back':'Welcome'}, ${esc(c.name)}!</h1><p class="hello-sub">${esc(back?LINES.backRest:LINES.welcomeRest)}</p><div class="hero-actions" style="justify-content:center"><button class="primary" id="helloGo">Start learning <span>→</span></button><button class="secondary" data-read>♫ Say hello again</button></div><button class="quiet" id="notMe">Not ${esc(c.name)}? Change name</button></div></section>`;
  document.getElementById('helloGo').onclick=()=>{pendingSpeech=null;setView('home');};document.getElementById('notMe').onclick=()=>setView('entry');const hb=app.querySelector('[data-read]');if(hb)hb.onclick=()=>{if(hb.classList.contains('reading'))stopSpeaking();else speak(greetParts(back));};if(autoGreet)speakSoon(greetParts(true));}
// True right after the name is entered (first greeting); returning visits say "Welcome back".
let freshGreeting=false;
function home(){const done=count(),started=Object.keys(state.records).length;const last=Object.entries(state.records).sort((a,b)=>b[1].last.localeCompare(a[1].last))[0];const resume=next(last?curriculum.find(m=>m.id===last[0]).subject:'math');app.innerHTML=`<section class="hero"><div><span class="pill"><span class="dot"></span>${childName()?"HI, "+esc(childName().toUpperCase())+"! A LITTLE EVERY DAY GOES A LONG WAY":"A LITTLE EVERY DAY GOES A LONG WAY"}</span><h1>Big wonders.<br><em>Little learners.</em></h1><p>A happy place to grow curious minds. Explore math, English, and science through small steps and playful practice.</p><div class="hero-actions"><button class="primary" data-start="${resume.id}">${started?'Keep growing':'Let’s start learning'} <span>↗</span></button><button class="quiet" data-parent>How it works →</button></div></div>${garden()}</section><section class="overview" aria-label="Learning progress"><div><strong class="welcome">${childName()?esc(childName())+(childName().endsWith("s")?"’":"’s"):"Your"} learning garden</strong><small>Every little step helps you grow.</small></div><div><strong>${done}<span style="font-size:13px;color:var(--muted)"> / 150</span></strong><small>Modules mastered</small></div><div><strong>${Object.values(state.records).reduce((sum,r)=>sum+r.attempts,0)}</strong><small>Practice sessions</small></div><div><strong>3</strong><small>Paths to discover</small></div></section><div class="section-line"><h2>Choose your adventure</h2><small>50 little steps in each subject</small></div><section class="subjects">${Object.entries(SUBJECTS).map(([s,d])=>`<article class="subject-card ${s}"><div class="card-art">${art(s)}</div><div class="card-body"><div class="card-kicker">${d.short}</div><h3>${d.name}</h3><p>${d.desc}</p><div class="progress-label"><span>${count(s)} of 50 mastered</span><span>${count(s)*2}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${count(s)*2}%"></div></div></div><button class="card-button" data-path="${s}"><span>${count(s)===50?'Explore again':count(s)?'Continue '+d.name:'Explore '+d.name}</span><span>→</span></button></article>`).join('')}</section><aside class="bottom-note"><span style="font-size:25px">✧</span><div><strong>Learning is better together.</strong><p>A grown-up can read along, lend a hand, and celebrate the small wins. Try one 10–15 minute module at a time.</p></div></aside>`;bind();}
function path(){const ms=curriculum.filter(m=>m.subject===subject),d=SUBJECTS[subject],n=next(subject);app.innerHTML=`<button class="back" data-home>← Back to your garden</button><div class="path-head"><div><div class="eyebrow">${d.short}</div><h1>Your ${d.name.toLowerCase()} adventure</h1><p>10 units. 50 small steps. Plenty of room to grow.</p></div><div class="path-stats"><strong>${count(subject)} / 50 mastered</strong><div class="progress-track" style="margin-top:12px"><div class="progress-fill" style="width:${count(subject)*2}%"></div></div></div></div><div class="notice">Get 4 of 5 right on your first try, then do the home activity, and the next step opens. Steps you finish stay open, so you can practice them again anytime.</div>${Array.from({length:10},(_,i)=>`<section class="unit"><div class="unit-title"><span>${String(i+1).padStart(2,'0')}</span><div><h2>${esc(ms[i*5].unit)}</h2><small>Modules ${i*5+1}–${i*5+5} · ${ms.slice(i*5,i*5+5).filter(m=>mastered(m.id)).length} of 5 mastered</small></div></div><div class="module-grid">${ms.slice(i*5,i*5+5).map(m=>`<button class="module-button ${mastered(m.id)?'done':m.id===n.id?'current':''}" data-start="${m.id}" ${!available(m)?'disabled':''}><span class="num">${mastered(m.id)?'✓':String(m.number).padStart(2,'0')}</span><strong>${esc(m.title)}</strong><small>${mastered(m.id)?'Mastered · practice again':!available(m)?'Opens after the step before':record(m.id)?'Keep practicing':'Ready to explore'}</small></button>`).join('')}</div></section>`).join('')}`;bind();}
function begin(id,preview=false){const m=curriculum.find(x=>x.id===id);if(!m||(!preview&&!available(m)))return;subject=m.subject;session={m,preview,step:'learn',index:0,score:0,first:true,answered:false,wrong:[],activity:false,questions:[...m.questions,...m.review]};preloadAudio(m);setView('lesson');autoSpeakParts(readParts());}
function lesson(){const s=session,m=s.m;let body='';let current=s.step==='learn'?0:s.step==='quiz'?1:s.step==='activity'?2:3;
const top=`<button class="back" data-back>← ${s.preview?'Grown-up corner':SUBJECTS[m.subject].name+' adventure'}</button><div class="lesson-top"><div><span class="eyebrow">${SUBJECTS[m.subject].name} · Module ${m.number} / 50 ${s.preview?'· PREVIEW':''}</span><h1>${esc(m.title)}</h1></div><button class="secondary" data-print>Print worksheet ↗</button></div><div class="lesson-tabs">${['Learn','Practice + review','Try at home','Celebrate'].map((t,i)=>`<span class="${i===current?'active':''}">${i+1}. ${t}</span>`).join('')}</div>`;
if(s.step==='learn')body=`<div class="panel"><div class="learn-icon">${SUBJECTS[m.subject].symbol}</div><h2>Let’s discover something!</h2><p class="lesson-copy">${sentences(m.learn).map(t=>`<span class="sentence">${esc(t)}</span>`).join(' ')}</p><button class="secondary" data-read>♫ Read this to me</button></div><div class="lesson-controls"><span class="notice">3 new questions and 2 ${m.number===1?'warm-up':'remember-this'} questions</span><button class="primary" data-practice>Try it together →</button></div>`;
else if(s.step==='quiz'){const question=s.questions[s.index];body=`<div class="panel"><div class="progress-label"><span>${s.index<3?'New skill':m.number===1?'Warm-up practice':'Remember this? '+esc(question.source)}</span><span>Question ${s.index+1} of 5</span></div><div class="progress-track"><div class="progress-fill" style="width:${s.index*20}%"></div></div><h2 class="question">${esc(question.prompt)}</h2><button class="secondary read-small" data-read>♫ Read it to me</button><div class="options">${question.options.map((o,i)=>`<button class="option" data-answer="${i}">${esc(o)}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div></div><div class="lesson-controls"><span class="notice">Take your time. You can always try again.</span><button id="nextQuestion" class="primary hidden">${s.index===4?'Time to try at home':'Next question'} →</button></div>`;}
else if(s.step==='activity')body=`<div class="panel"><span class="eyebrow">A LITTLE LESS SCREEN, A LITTLE MORE DISCOVERY</span><h2 style="margin-top:18px">Now try it at home</h2><div class="activity-box">${esc(m.activity)}</div><p class="notice">A grown-up should guide this activity. Spoken answers and drawings both count. Skip anything your child is not ready for and come back later.</p><button class="secondary" data-read>♫ Read the activity</button><label class="check-row"><input type="checkbox" id="activityDone"><span>We tried this activity and talked about what we learned.</span></label></div><div class="lesson-controls"><span class="notice">${s.preview?'Preview does not save progress.':'You got '+s.score+' of 5 right on your first try.'}</span><button class="primary" id="finishLesson" disabled>Celebrate our step ✧</button></div>`;
else {const passed=s.score>=4;body=`<div class="panel" style="text-align:center"><div class="result-flower">✿</div><h2 class="result-title">${RESULT[resultKind(s)].title}</h2><p class="lesson-copy">${childName()?esc(childName())+", you got ":""}${s.score} of 5 right on your first try.</p><p class="result-line">${RESULT[resultKind(s)].line}</p>${s.wrong.length?`<div class="notice">Skills to revisit: ${[...new Set(s.wrong.map(id=>curriculum.find(x=>x.id===id).title))].map(esc).join(', ')}.</div>`:''}<div class="hero-actions" style="justify-content:center"><button class="primary" data-retry>Practice again ↻</button><button class="secondary" data-back>${s.preview?'Back to grown-up corner':'Back to path'} →</button>${!s.preview&&passed&&m.number<50?`<button class="secondary" data-start="${m.subject}-${m.number+1}">Next module →</button>`:''}</div></div>`;}
app.innerHTML=`<section class="lesson">${top}${body}</section>`;bind();app.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{if(b.classList.contains('reading'))stopSpeaking();else speak(readParts());});if(s.step==='quiz'){app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer),b));document.getElementById('nextQuestion').onclick=()=>{s.index++;s.first=true;s.answered=false;if(s.index===5)s.step='activity';render();autoSpeakParts(readParts());};}if(s.step==='activity'){document.getElementById('activityDone').onchange=e=>{s.activity=e.target.checked;document.getElementById('finishLesson').disabled=!s.activity;};document.getElementById('finishLesson').onclick=finish;}const practice=app.querySelector('[data-practice]');if(practice)practice.onclick=()=>{s.step='quiz';render();autoSpeakParts(readParts());};const retry=app.querySelector('[data-retry]');if(retry)retry.onclick=()=>begin(m.id,s.preview);}
function readText(){const s=session;if(s.step==='learn')return s.m.learn;if(s.step==='activity')return s.m.activity;if(s.step==='quiz'){const q=s.questions[s.index];return q.prompt+'. Choices: '+q.options.join('. ');}return '';}
function hintFor(q){return (questionRef(q).m||session.m).learn;}
function answer(i,b){const s=session;if(s.answered)return;const q=s.questions[s.index],correct=q.options[i]===q.answer;const fb=document.getElementById('feedback');
if(correct){if(s.first)s.score++;s.answered=true;b.classList.add('correct');app.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);const cheer=PRAISE[praiseTurn++%PRAISE.length];fb.innerHTML=`<div class="feedback"><strong>${esc(cheer)} ✧</strong><br>${esc(q.why)}</div>`;document.getElementById('nextQuestion').classList.remove('hidden');{const r=questionRef(q),n=(praiseTurn-1)%PRAISE.length;autoSpeakParts([{text:cheer,clip:'common:P'+n},{text:speakable(q.why),clip:r.j>=0?r.m.id+':W'+r.j:null}]);}}
else{if(s.first)s.wrong.push(q.sourceId||s.m.id);s.first=false;b.classList.add('wrong');b.disabled=true;const nudge=RETRY[retryTurn++%RETRY.length],hint=hintFor(q);fb.innerHTML=`<div class="feedback retry"><strong>${esc(nudge)}</strong><br><span class="hint-label">Little hint:</span> ${esc(hint)}</div>`;{const n=(retryTurn-1)%RETRY.length,src=questionRef(q).m||s.m;autoSpeakParts([{text:nudge,clip:'common:R'+n},{text:LINES.hint,clip:'common:hint'},...learnParts(src)]);}}}
function finish(){const s=session;if(!s.activity)return;if(!s.preview){const old=record(s.m.id);state.records[s.m.id]={best:Math.max(old?.best||0,s.score),mastered:!!old?.mastered||s.score>=4,attempts:(old?.attempts||0)+1,activity:true,last:new Date().toISOString(),missed:[...new Set(s.wrong)]};save();}s.step='result';render();autoSpeakParts(readParts());}
function voiceOptions(){const vs=voiceList(),story=useStoryteller(),cur=story?null:pickVoice();const head=hasRecordings()?`<option value="storyteller" ${story?'selected':''}>Storyteller · recorded natural voice ★</option>`:'';const dev=vs.map(v=>`<option value="${esc(v.name)}" ${cur&&v.name===cur.name?'selected':''}>${esc(v.name.replace(/^(Microsoft|Google)\s+/,''))} · ${esc(v.lang)}</option>`).join('');return head+(dev?`<optgroup label="This device’s voices">${dev}</optgroup>`:(head?'':'<option value="">Device default voice</option>'));}
function voicePanel(){return `<section class="panel voice-panel"><h2>Read-aloud voice</h2><p>Every lesson, question, answer choice, cheer, and welcome is read by the Storyteller, a natural recorded voice that sounds the same on every device.</p><fieldset class="field rate-field"><legend>Speed</legend><label><input type="radio" name="rate" value="slow" ${state.rate==='slow'?'checked':''}> Slow and clear</label><label><input type="radio" name="rate" value="normal" ${state.rate!=='slow'?'checked':''}> Natural</label></fieldset><button class="secondary" id="voiceSample">♫ Hear a sample</button><p class="small-note">The Storyteller greets Fanu and Fife by name. Other children are welcomed as “little sprout”, and their name appears on screen.</p></section>`;}
function bindVoicePanel(){if(!document.getElementById('voiceSample'))return;app.querySelectorAll('input[name="rate"]').forEach(r=>r.onchange=()=>{state.rate=r.value;save();say(LINES.hello,'common:hello');});document.getElementById('voiceSample').onclick=()=>say(LINES.sample,'common:sample');}
function parent(){const needs=[...new Set(Object.values(state.records).flatMap(r=>r.missed))].map(id=>curriculum.find(m=>m.id===id)).filter(m=>m);app.innerHTML=`<button class="back" data-home>← Back to your garden</button><div class="eyebrow">FOR YOUR CHILD’S FIRST TEACHER</div><h1 style="font-size:37px">Grown-up corner</h1><p style="color:var(--muted);max-width:680px">A gentle plan, useful progress, and plenty of encouragement. This is guided practice for a kindergartener, with you alongside.</p><div class="learner-card">${avatar(state.child.gender)}<div><small>LEARNER ON THIS DEVICE</small><strong>${esc(childName()||"Not set")}</strong><span>${state.child.gender==="boy"?"Follow his progress below.":state.child.gender==="girl"?"Follow her progress below.":"Follow your learner’s progress below."}${COLORS[state.child.color]?` Favorite color: <i class="swatch" style="background:${COLORS[state.child.color].hex}"></i>${COLORS[state.child.color].name}.`:""}</span></div><button class="secondary" id="changeLearner">Change name, gender, or color</button></div><div class="parent-grid"><section class="panel"><h2>A little every day</h2><p>Try one module for 10–15 minutes. Rotate math, English, and science. Read instructions aloud, let your child explain their thinking, and stop for a break when needed.</p><p>Each subject has 10 units with 5 modules. Every module includes teaching, 3 focus questions, 2 questions from earlier lessons (warm-ups in module 1), and a hands-on activity.</p><p>Four of five correct first choices plus the home activity marks a module mastered and unlocks the next. Wrong choices get helpful feedback and another try. Later practice never removes earlier mastery.</p><p>These are practice indicators, not a grade or a full assessment. Early English work uses familiar words; help with reading is expected. For reading questions, let your child try to read first, then use read aloud as a helper.</p></section><section class="panel"><h2>Your learning snapshot</h2><table><thead><tr><th>Subject</th><th>Mastered</th><th>Next step</th></tr></thead><tbody>${Object.entries(SUBJECTS).map(([s,d])=>`<tr><td>${d.name}</td><td>${count(s)} / 50</td><td>${count(s)===50?'Practice favorites':'Module '+next(s).number}</td></tr>`).join('')}</tbody></table><p>Progress lives in this browser on this device. It does not sync between devices. Clearing browser data removes it. Export a backup to keep or move it.</p><div class="print-controls"><button class="secondary" id="exportProgress">Export progress</button><label class="secondary import-label">Import backup<input id="importProgress" type="file" accept=".json,application/json" class="hidden"></label></div><p id="backupMessage" role="status"></p><button class="quiet danger" id="resetProgress">Reset all progress</button></section>${voicePanel()}<section class="panel"><h2>A little extra practice</h2><p>These skills had a missed first choice in a recent completed attempt. Practice is always welcome.</p>${needs.length?needs.slice(0,12).map(m=>`<div class="review-item"><span>${SUBJECTS[m.subject].name} · ${esc(m.title)}</span><button class="secondary" data-start="${m.id}" data-preview="${!available(m)}">Practice</button></div>`).join(''):'<p>No skills to revisit yet. Finish a module to see helpful practice suggestions here.</p>'}</section><section class="panel"><h2>Print & learn away from screens</h2><p>Every module has a printable worksheet with a name line, teaching reminder, five questions, a drawing space, and a separate answer-key page. Print only the child’s page if you want to keep answers separate.</p><p>Use the curriculum browser below to preview or print any lesson. Preview sessions do not change progress or unlock lessons.</p><p>Science activities use safe everyday objects with adult help. Do not taste unknown items. Use only large enclosed magnets with an adult, and supervise any water activity.</p></section></div><div class="section-line" style="margin-top:34px"><h2>Browse all 150 modules</h2><small>Preview any lesson</small></div><div class="print-controls">${Object.entries(SUBJECTS).map(([s,d])=>`<button class="${s===subject?'primary':'secondary'}" data-browse="${s}">${d.name}</button>`).join('')}</div>${Array.from({length:10},(_,i)=>{const ms=curriculum.filter(m=>m.subject===subject).slice(i*5,i*5+5);return `<section class="unit"><div class="unit-title"><span>${i+1}</span><h2>${esc(ms[0].unit)}</h2></div><div class="module-grid">${ms.map(m=>`<button class="module-button" data-start="${m.id}" data-preview="true"><span class="num">${m.number}</span><strong>${esc(m.title)}</strong><small>Preview & print ↗</small></button>`).join('')}</div></section>`;}).join('')}`;bind();app.querySelectorAll('[data-browse]').forEach(b=>b.onclick=()=>{subject=b.dataset.browse;const y=window.scrollY;render();window.scrollTo(0,y);});document.getElementById('exportProgress').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='little-sprout-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.getElementById('importProgress').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('This file is too large.');const s=JSON.parse(await f.text());if(s.version!==1||!validState(s))throw Error('This is not a valid Little Sprout backup.');if(!confirm('Replace this browser’s progress with the imported backup?'))return;state={records:s.records,sound:!!s.sound,voice:state.voice,rate:state.rate,child:s.child?cleanChild(s.child):state.child};save();render();toast('Your backup has been imported.');}catch(err){document.getElementById('backupMessage').textContent=err.message;}};bindVoicePanel();document.getElementById('changeLearner').onclick=()=>setView('entry');document.getElementById('resetProgress').onclick=()=>{if(confirm('Reset all learning progress on this device? Export a backup first if you want to keep it.')){state.records={};save();render();toast('Progress has been reset.');}};}
function worksheet(m){document.querySelector('.print-sheet')?.remove();const qs=[...m.questions,...m.review];const sheet=document.createElement('section');sheet.className='print-sheet';sheet.innerHTML=`<small>LITTLE SPROUT · ${SUBJECTS[m.subject].name.toUpperCase()} · MODULE ${m.number} OF 50</small><h1>${esc(m.title)}</h1><p class="name-line">Name: _______________________ Date: ______________</p><p>${esc(m.learn)}</p>${qs.map((q,i)=>`<div class="print-question"><strong>${i+1}. ${esc(q.prompt)}</strong><p class="options-print">${q.options.map(esc).join('   /   ')}</p><div class="answer-line"></div></div>`).join('')}<h2>Try it at home</h2><p>${esc(m.activity)}</p><div class="draw-box"></div><p>A grown-up can read aloud. Draw or talk about your answer.</p><p class="print-dedication">Inspired and proudly made for FANU and FIFE</p><div class="key"><small>GROWN-UP ANSWER KEY</small><h1>${esc(m.title)}</h1>${qs.map((q,i)=>`<p><strong>${i+1}. ${esc(q.answer)}</strong><br>${esc(q.why)}${i>2?'<br>Review: '+esc(q.source):''}</p>`).join('')}<p>Home activity: answers and drawings vary. Ask your child to explain what they noticed.</p></div>`;document.body.appendChild(sheet);window.print();}
function bind(){app.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>setView('home'));app.querySelectorAll('[data-parent]').forEach(b=>b.onclick=()=>setView('parent'));app.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>{subject=b.dataset.path;setView('path');});app.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>begin(b.dataset.start,b.dataset.preview==='true'));app.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>setView(session.preview?'parent':'path'));app.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>worksheet(session.m));}
document.getElementById('homeNav').onclick=()=>setView('home');document.querySelector('.brand').onclick=e=>{e.preventDefault();setView('home');};document.getElementById('parentNav').onclick=()=>setView('parent');document.getElementById('soundToggle').onclick=()=>{state.sound=!state.sound;save();document.getElementById('soundToggle').textContent=state.sound?'♫ Read aloud: on':'♫ Read aloud: off';document.getElementById('soundToggle').setAttribute('aria-pressed',String(state.sound));if(state.sound)say(LINES.on,'common:on');else stopSpeaking();};view=profileDone()?'hello':'entry';render();
